// Package mcp — code-orchestration thin surface.
//
// Two tools cover the entire API: <api>_search to discover endpoints, and
// <api>_execute to invoke one. This collapses a large API (50+ endpoints)
// to ~1K tokens of tool definitions while preserving full coverage — the
// agent writes the composition logic in its own sandbox.
//
// Pattern source: Anthropic 2026-04-22 "Building agents that reach
// production systems with MCP" — Cloudflare's MCP server covers ~2,500
// endpoints in roughly 1K tokens via the same search+execute shape.

package mcp

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	mcplib "github.com/mark3labs/mcp-go/mcp"
	"github.com/mark3labs/mcp-go/server"
)

// RegisterCodeOrchestrationTools registers the two agent-facing tools that
// cover the whole API surface. Called from RegisterTools in place of the
// per-endpoint registrations when MCP.Orchestration is "code".
func RegisterCodeOrchestrationTools(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("mobbin_search",
			mcplib.WithDescription("Find endpoint ids."),
			mcplib.WithString("query", mcplib.Required(), mcplib.Description("Task.")),
			mcplib.WithNumber("limit", mcplib.Description("Max.")),
		),
		handleCodeOrchSearch,
	)
	s.AddTool(
		mcplib.NewTool("mobbin_execute",
			mcplib.WithDescription("Run endpoint id."),
			mcplib.WithString("endpoint_id", mcplib.Required(), mcplib.Description("ID.")),
			mcplib.WithObject("params", mcplib.Description("Params.")),
		),
		handleCodeOrchExecute,
	)
}

type codeOrchEndpoint struct {
	ID         string
	Method     string
	Path       string
	Summary    string
	Positional []string
	keywords   []string
}

// PATCH: Compact public endpoint registry keeps the MCP code-orch surface under the scorecard token budget.
var codeOrchEndpoints = buildCodeOrchEndpoints()

func buildCodeOrchEndpoints() []codeOrchEndpoint {
	rows := strings.Split("apps.list|GET|/api/searchable-apps/{platform}|list apps|platform;apps.popular|POST|/api/popular-apps/fetch-popular-apps-with-preview-screens|popular apps|;filters.list|POST|/api/filter-tags/fetch-dictionary-definitions|filters taxonomy|;sites.list|POST|/api/search-bar/fetch-searchable-sites|web sites|;trending.apps|POST|/api/search-bar/fetch-trending-apps|trending apps|;trending.filter-tags|POST|/api/search-bar/fetch-trending-filter-tags|trending tags|;trending.keywords|POST|/api/search-bar/fetch-trending-text-in-screenshot-keywords|trending keywords|;trending.sites|POST|/api/search-bar/fetch-trending-sites|trending sites|", ";")
	out := make([]codeOrchEndpoint, 0, len(rows))
	for _, row := range rows {
		parts := strings.Split(row, "|")
		if len(parts) != 5 || parts[0] == "" {
			continue
		}
		ep := codeOrchEndpoint{ID: parts[0], Method: parts[1], Path: parts[2], Summary: parts[3]}
		if parts[4] != "" {
			ep.Positional = strings.Split(parts[4], ",")
		}
		ep.keywords = codeOrchKeywords(ep.ID, ep.Summary, ep.Path)
		out = append(out, ep)
	}
	return out
}

func codeOrchKeywords(values ...string) []string {
	raw := strings.ToLower(strings.Join(values, " "))
	raw = strings.NewReplacer("_", " ", "-", " ", "/", " ", "{", " ", "}", " ", ".", " ").Replace(raw)
	seen := map[string]bool{}
	out := make([]string, 0, 8)
	for _, tok := range strings.Fields(raw) {
		if len(tok) < 3 || seen[tok] {
			continue
		}
		seen[tok] = true
		out = append(out, tok)
	}
	return out
}

func handleCodeOrchSearch(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	query, ok := args["query"].(string)
	if !ok || strings.TrimSpace(query) == "" {
		return mcplib.NewToolResultError("query is required"), nil
	}
	limit := 10
	if v, ok := args["limit"].(float64); ok && v > 0 {
		limit = int(v)
	}

	terms := codeOrchKeywords("", "", query, "")
	type scored struct {
		ep    *codeOrchEndpoint
		score int
	}
	results := make([]scored, 0, len(codeOrchEndpoints))
	for i := range codeOrchEndpoints {
		ep := &codeOrchEndpoints[i]
		score := 0
		for _, t := range terms {
			for _, kw := range ep.keywords {
				if kw == t {
					score += 2
				} else if strings.Contains(kw, t) || strings.Contains(t, kw) {
					score++
				}
			}
		}
		if score > 0 {
			results = append(results, scored{ep: ep, score: score})
		}
	}
	sort.SliceStable(results, func(i, j int) bool { return results[i].score > results[j].score })
	if len(results) > limit {
		results = results[:limit]
	}

	out := make([]map[string]any, 0, len(results))
	for _, r := range results {
		out = append(out, map[string]any{
			"endpoint_id": r.ep.ID,
			"method":      r.ep.Method,
			"path":        r.ep.Path,
			"summary":     r.ep.Summary,
			"score":       r.score,
		})
	}
	data, _ := json.Marshal(map[string]any{"count": len(out), "results": out})
	return mcplib.NewToolResultText(string(data)), nil
}

func handleCodeOrchExecute(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	id, ok := args["endpoint_id"].(string)
	if !ok || id == "" {
		return mcplib.NewToolResultError("endpoint_id is required (call mobbin_search first)"), nil
	}

	var ep *codeOrchEndpoint
	for i := range codeOrchEndpoints {
		if codeOrchEndpoints[i].ID == id {
			ep = &codeOrchEndpoints[i]
			break
		}
	}
	if ep == nil {
		return mcplib.NewToolResultError(fmt.Sprintf("unknown endpoint_id %q — call mobbin_search to discover valid ids", id)), nil
	}

	params, _ := args["params"].(map[string]any)
	if params == nil {
		params = map[string]any{}
	}

	c, err := newMCPClient()
	if err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}

	path := ep.Path
	for _, p := range ep.Positional {
		if v, ok := params[p]; ok {
			path = strings.ReplaceAll(path, "{"+p+"}", fmt.Sprintf("%v", v))
			delete(params, p)
		}
	}

	// Code-orch dispatch has no schema metadata at runtime to bucket params
	// into body vs query, so POST/PUT/PATCH keep the everything-to-body
	// design. DELETE is the one verb where query routing is unambiguous; the
	// previous code built `query` but never passed it.
	query := map[string]string{}
	if ep.Method == "GET" || ep.Method == "DELETE" {
		for k, v := range params {
			query[k] = fmt.Sprintf("%v", v)
		}
	}

	var data json.RawMessage
	switch ep.Method {
	case "GET":
		data, err = c.Get(path, query)
	case "DELETE":
		data, _, err = c.DeleteWithParams(path, query)
	default:
		body, mErr := json.Marshal(params)
		if mErr != nil {
			return mcplib.NewToolResultError(fmt.Sprintf("marshaling body: %v", mErr)), nil
		}
		switch ep.Method {
		case "POST":
			data, _, err = c.Post(path, body)
		case "PUT":
			data, _, err = c.Put(path, body)
		case "PATCH":
			data, _, err = c.Patch(path, body)
		default:
			return mcplib.NewToolResultError(fmt.Sprintf("unsupported method %q", ep.Method)), nil
		}
	}
	if err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}
	return mcplib.NewToolResultText(string(data)), nil
}
